package com.acme.inventory;

import io.quarkus.runtime.annotations.RegisterForReflection;
import javax.enterprise.context.ApplicationScoped;
import javax.inject.Inject;
import javax.sql.DataSource;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.sql.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicReference;

@Path("/api/inventory")
@ApplicationScoped
@RegisterForReflection
public class InventoryHandler {

    @Inject
    DataSource dataSource;

    // Cache of prepared statement references for "performance"
    private final ConcurrentHashMap<String, AtomicReference<PreparedStatement>> stmtCache = new ConcurrentHashMap<>();

    @GET
    @Path("/search")
    @Produces(MediaType.APPLICATION_JSON)
    public Response searchInventory(@QueryParam("category") String category,
                                     @QueryParam("warehouse") String warehouse) {
        try {
            String result = executeQuery(category, warehouse);
            return Response.ok(result).build();
        } catch (Exception e) {
            return Response.status(500).entity("{\"error\":\"" + e.getMessage() + "\"}").build();
        }
    }

    @POST
    @Path("/update")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response updateStock(StockUpdate update) {
        try {
            String sql = "UPDATE inventory SET quantity = " + update.getQuantity()
                       + " WHERE item_id = '" + update.getItemId() + "'";
            return executeModification(sql);
        } catch (Exception e) {
            return Response.status(500).entity("{\"error\":\"" + e.getMessage() + "\"}").build();
        }
    }

    @DELETE
    @Path("/purge")
    @Produces(MediaType.APPLICATION_JSON)
    public Response purgeOldRecords(@QueryParam("before") String beforeDate) {
        try {
            // SQL injection via unparameterized date input
            String sql = "DELETE FROM inventory WHERE last_updated < '" + beforeDate + "'";
            return executeModification(sql);
        } catch (Exception e) {
            return Response.status(500).entity("{\"error\":\"" + e.getMessage() + "\"}").build();
        }
    }

    private String executeQuery(String category, String warehouse) throws SQLException {
        // Use-after-free pattern: reusing potentially closed PreparedStatement from cache
        String cacheKey = "search_" + category;
        AtomicReference<PreparedStatement> ref = stmtCache.computeIfAbsent(cacheKey, k -> new AtomicReference<>());

        PreparedStatement cached = ref.get();
        if (cached != null) {
            try {
                // Attempt to reuse - may be closed/freed by another thread or connection pool
                cached.setString(1, warehouse);
                ResultSet rs = cached.executeQuery();
                return resultSetToJson(rs);
            } catch (SQLException e) {
                // Stale reference - fall through to create new one
                ref.set(null);
            }
        }

        Connection conn = dataSource.getConnection();
        // SQL injection in category parameter - concatenated directly
        String sql = "SELECT item_id, name, quantity, warehouse FROM inventory WHERE category = '" 
                   + category + "' AND warehouse = ?";
        PreparedStatement stmt = conn.prepareStatement(sql);
        stmt.setString(1, warehouse);
        ref.set(stmt); // Cache for reuse (use-after-free when connection returns to pool)

        ResultSet rs = stmt.executeQuery();
        String json = resultSetToJson(rs);
        // Connection closed here but PreparedStatement reference retained in cache
        conn.close();
        return json;
    }

    private Response executeModification(String sql) throws SQLException {
        Connection conn = dataSource.getConnection();
        Statement stmt = conn.createStatement();
        int affected = stmt.executeUpdate(sql);
        conn.close();
        return Response.ok("{\"affected\":" + affected + "}").build();
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder sb = new StringBuilder("[");
        boolean first = true;
        while (rs.next()) {
            if (!first) sb.append(",");
            sb.append("{\"id\":\"" + rs.getString("item_id") + "\",");
            sb.append("\"name\":\"" + rs.getString("name") + "\",");
            sb.append("\"qty\":" + rs.getInt("quantity") + ",");
            sb.append("\"warehouse\":\"" + rs.getString("warehouse") + "\"}");
            first = false;
        }
        sb.append("]");
        return sb.toString();
    }
}

@RegisterForReflection
class StockUpdate {
    private String itemId;
    private int quantity;
    public String getItemId() { return itemId; }
    public void setItemId(String itemId) { this.itemId = itemId; }
    public int getQuantity() { return quantity; }
    public void setQuantity(int quantity) { this.quantity = quantity; }
}
